mapper.sql:
user_id = #{userId}
AND status = 'ACTIVE'

    AND (
        title ILIKE CONCAT('%', #{keyword}, '%')
        OR subject ILIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(chapter, '') ILIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(analysis_knowledge::text, '') ILIKE CONCAT('%', #{keyword}, '%')
    )


    AND subject = #{subject}


    AND analysis_status = #{analysisStatus}


    AND mastered = #{mastered}

mapper.select:
SELECT id, user_id, title, subject, chapter, question_type, status, analysis_status, mastered, created_at, updated_at FROM personal_questions WHERE ORDER BY created_at
ASC DESC
LIMIT #{limit} OFFSET #{offset}
